// Üretilen dosya: tool/ozgun/uret.py. Biyoloji · Hücre organelleri ve zar taşıma ayrıntılı (kolay).
const ozBiology6Kolay = <(String, String, List<String>, String)>[
  ('Tek mercekli, kendi yaptığı mikroskoplarla 1670\'lerde göl suyunda ve diş kirinde canlı mikroorganizmaları ilk kez gözlemleyip "küçük hayvancıklar" olarak tanımlayan bilim insanı kimdir?', 'Antonie van Leeuwenhoek', ['Robert Hooke', 'Matthias Schleiden', 'Louis Pasteur'], 'Hollandalı Leeuwenhoek, büyütmesi yüksek tek mercekli mikroskoplarıyla bakteri ve protistleri ilk gözlemleyen kişi olarak kabul edilir. Hooke ise ölü mantar dokusunu incelemişti.'),
  ('1831\'de orkide yaprağı hücrelerini incelerken hücrelerin içinde düzenli olarak bulunan yuvarlak yapıyı tanımlayıp ona "çekirdek" (nucleus) adını veren İskoç botanikçi kimdir?', 'Robert Brown', ['Robert Hooke', 'Theodor Schwann', 'Camillo Golgi'], 'Robert Brown çekirdeği 1831\'de tanımlamıştır; adı aynı zamanda sıvıdaki taneciklerin düzensiz hareketine (Brown hareketi) de verilmiştir.'),
  ('"Omnis cellula e cellula" (her hücre başka bir hücreden gelir) ilkesini 1855\'te yaygınlaştırarak hücre kuramına üçüncü temel önermeyi ekleyen bilim insanı kimdir?', 'Rudolf Virchow', ['Theodor Schwann', 'Anton van Leeuwenhoek', 'Gregor Mendel'], 'Alman hekim Rudolf Virchow, yeni hücrelerin ancak var olan hücrelerin bölünmesiyle oluştuğunu savunmuş ve bu ilke hücre kuramının parçası olmuştur.'),
  ('Gümüş nitratlı boyama ("kara tepkime") yöntemiyle sinir hücrelerini incelerken 1898\'de hücre içindeki yassı kesecik yığınını tanımlayan ve organele adını veren İtalyan bilim insanı kimdir?', 'Camillo Golgi', ['Santiago Ramón y Cajal', 'Marcello Malpighi', 'Rudolf Virchow'], 'Golgi cisimciği, kendisini gümüş boyamayla ilk kez tanımlayan Camillo Golgi\'nin adını taşır.'),
  ('Elektron mikroskobuyla ribozomları ilk kez ayrıntılı tanımlayan ve salgı proteinlerinin hücre içindeki yolunu ortaya koyan çalışmalarıyla 1974 Nobel Ödülü\'nü paylaşan bilim insanı kimdir?', 'George Palade', ['Christian de Duve', 'Albert Claude', 'Peter Agre'], 'Ribozomlar bir dönem "Palade tanecikleri" olarak anıldı. Palade, Claude ve de Duve 1974 Nobel Fizyoloji veya Tıp Ödülü\'nü hücrenin yapısal ve işlevsel düzenine ilişkin bulguları için paylaştı.'),
  ('Standart bir ışık mikroskobunun ayırt edebileceği iki nokta arasındaki en küçük uzaklık (ayırma gücü sınırı) yaklaşık ne kadardır?', '0,2 mikrometre', ['2 milimetre', '0,2 nanometre', '20 mikrometre'], 'Görünür ışığın dalga boyu nedeniyle ışık mikroskobunun ayırma gücü yaklaşık 0,2 µm (200 nm) ile sınırlıdır. Bu yüzden ribozom gibi yapılar ışık mikroskobunda seçilemez.'),
  ('1000 kat büyütmeyle çekilmiş bir fotoğrafta bir hücrenin çapı 15 mm olarak ölçülüyor. Hücrenin gerçek çapı kaç mikrometredir?', '15 µm', ['1,5 µm', '150 µm', '0,15 µm'], 'Gerçek boy = görüntü boyu / büyütme = 15 mm / 1000 = 0,015 mm. 1 mm = 1000 µm olduğundan 0,015 mm = 15 µm eder.'),
  ('Diferansiyel santrifüjde parçalanmış hücre özütü giderek artan hızlarda döndürülüyor. Aşağıdakilerden hangisi en düşük hızda çökeltiye geçen yapıdır?', 'Çekirdek', ['Ribozom', 'Endoplazmik retikulum parçaları', 'Mitokondri'], 'Diferansiyel santrifüjde büyük ve ağır yapılar önce çöker: önce çekirdekler, sonra mitokondri ve kloroplastlar, sonra ER parçaları (mikrozomlar), en son ribozomlar.'),
  ('Tipik bir bakteri hücresi ile tipik bir hayvan hücresinin çapları karşılaştırıldığında hangi eşleştirme gerçeğe en yakındır?', 'Bakteri 1–5 µm, hayvan hücresi 10–30 µm', ['Bakteri 10–30 µm, hayvan hücresi 1–5 µm', 'Bakteri 1–5 nm, hayvan hücresi 10–30 nm', 'İkisi de yaklaşık 1 mm büyüklüğündedir'], 'Prokaryot hücreler genellikle birkaç mikrometre boyundadır; ökaryot hayvan hücreleri ise çoğunlukla bunun yaklaşık on katı büyüklüktedir.'),
  ('İnsan vücudunda tek bir hücrenin uzantısının bir metreye yaklaşabildiği hücre tipi hangisidir?', 'Motor sinir hücresi', ['Olgun bir alyuvar', 'Çok çekirdekli uzun bir çizgili iskelet kası lifi', 'Karaciğer hücresi'], 'Omurilikten ayak kaslarına uzanan motor nöronların aksonları yaklaşık 1 m uzunluğa ulaşabilir; bu yüzden nöronlar insandaki en uzun hücrelerdir.'),
  ('Hücre zarının kalınlığı aşağıdakilerden hangisine en yakındır?', 'Yaklaşık 7–8 nanometre', ['Yaklaşık 7–8 mikrometre', 'Yaklaşık 0,7 milimetre', 'Yaklaşık 70 mikrometre'], 'Hücre zarı yalnızca birkaç nanometre kalınlığındadır (yaklaşık 7–8 nm); bu yüzden ancak elektron mikroskobunda çift çizgi hâlinde görülebilir.'),
  ('Küre biçimli bir hücrede yüzey/hacim oranı 3/r ile hesaplanır. Yarıçapı 3 µm olan bir hücrenin yarıçapı 6 µm\'ye çıkarsa bu oran kaç olur?', '0,5 µm⁻¹', ['1 µm⁻¹', '2 µm⁻¹', '0,25 µm⁻¹'], '3/r formülüyle r = 6 µm için oran 3/6 = 0,5 µm⁻¹ olur. Yarıçap iki katına çıkınca oran yarıya iner.'),
  ('Bitki köklerindeki emici tüylerin, epidermis hücrelerinin ince uzun çıkıntıları biçiminde olması hücre düzeyinde hangi sonucu doğurur?', 'Emici yüzeyin hacme göre büyümesi', ['Hücrenin fotosentez yapabilmesi', 'Hücre duvarının kalınlaşıp odunlaşarak köke destek sağlaması', 'Hücrenin çekirdeğinin bölünmesi'], 'Uzun ince çıkıntı biçimi yüzey/hacim oranını büyütür; böylece kök tüyü hücreleri topraktan su ve mineral almada çok etkili olur.'),
  ('Hem su seven hem de su sevmeyen bölgeler taşıyan fosfolipit gibi moleküller kimyasal olarak nasıl adlandırılır?', 'Amfipatik', ['Hidrofobik', 'İyonik', 'Apolar'], 'Amfipatik moleküller suyla etkileşen polar bir baş ve sudan kaçan apolar kuyruklar içerir; zar oluşumunu sağlayan özellik budur.'),
  ('Yapay olarak hazırlanmış fosfolipit çift katmanından oluşan, içine ilaç doldurulabilen küçük küresel keseciklere ne ad verilir?', 'Lipozom', ['Lizozom', 'Nükleozom', 'Ribozom'], 'Lipozomlar, fosfolipitlerin suda kendiliğinden kapalı kesecik oluşturması özelliğinden yararlanılarak hazırlanır ve ilaç ya da aşı taşımada kullanılır.'),
  ('Glikolipitlerin karbonhidrat kısımları hücre zarının hangi yüzünde bulunur?', 'Yalnız hücre dışına bakan yüzünde', ['Yalnız sitoplazmaya bakan yüzünde', 'İki yüzünde eşit miktarda', 'Zarın iki katmanı arasında'], 'Glikolipit ve glikoproteinlerin şeker zincirleri Golgi\'de eklenir ve kesecik zarının iç yüzü hücre zarının dış yüzüne dönüştüğü için daima hücre dışına bakar.'),
  ('Etil alkolün mideden bile hızla emilip hücrelere kolayca girmesinin başlıca nedeni nedir?', 'Küçük ve lipitte çözünebilir olması', ['Özel bir pompa ile ATP harcanarak taşınması', 'Mide asidiyle tepkimeye girip iyonlarına ayrışması', 'Büyük ve yüklü bir molekül olması'], 'Etanol küçük ve hem suda hem lipitlerde çözünebilen bir moleküldür; bu yüzden taşıyıcıya gerek duymadan zarlardan basit difüzyonla geçer.'),
  ('Hücre zarındaki proteinlerin bir kısmının hücre iskeletine, bir kısmının da hücre dışı matrikse bağlanmasının hücreye sağladığı başlıca yarar nedir?', 'Biçimin korunması ve dokuya tutunma', ['Hücrenin DNA\'sını eşlemesi', 'Hücrede mitokondri sayısını artırarak ATP üretimini başlatması', 'Zardan su geçişini durdurması'], 'Bağlantı işlevli zar proteinleri iç iskeleti dış matrikse bağlar; böylece hücre biçimi korunur ve hücre dokuda belirli bir konumda tutunur.'),
  ('Kültürde çoğalan normal hücreler, kap tabanını tek kat hâlinde kaplayıp birbirine değdiklerinde bölünmeyi durdururken kanser hücreleri üst üste yığılmaya devam eder. Kanser hücrelerinde kaybolan bu özelliğe ne ad verilir?', 'Temas inhibisyonu', ['Turgor basıncı', 'Seçici geçirgenlik', 'Otofaji'], 'Normal hücreler yüzey molekülleriyle komşularını algılayıp çoğalmayı durdurur. Kanser hücrelerinde bu temas inhibisyonu bozulduğu için düzensiz yığılma görülür.'),
  ('Doku nakli yapılacak bir hastada nakil öncesi doku uygunluğu testleri yapılır. Bu testlerin dayandığı hücresel temel hangisidir?', 'Bireye özgü yüzey glikoproteinleri', ['Hücrelerin aynı sayıda mitokondri taşıması', 'Hücrelerin aynı büyüklükte ve aynı biçimde olması', 'Bütün hücrelerde aynı çekirdek zarı bulunması'], 'Her bireyin hücre yüzeyinde kendine özgü tanıma molekülleri bulunur; bu moleküller uyuşmazsa alıcının bağışıklık sistemi nakledilen dokuyu yabancı olarak tanıyıp reddeder.'),
  ('Epitel hücrelerini alttaki bazal laminaya (hücre dışı matrikse) bağlayan, desmozomun yarısına benzeyen bağlantı hangisidir?', 'Hemidesmozom', ['Sıkı bağlantı', 'Geçit bağlantısı', 'Plazmodezma'], 'Hemidesmozomlar hücre içindeki ara filamentleri integrinler aracılığıyla bazal laminaya bağlar; böylece epitel altındaki dokuya sıkıca tutunur.'),
  ('Memelilerde vücuttaki toplam proteinin yaklaşık dörtte birini oluşturan ve hücre dışı matriksin başlıca lifli proteini olan molekül hangisidir?', 'Kollajen', ['Hemoglobin', 'Aktin', 'Keratin'], 'Kollajen; deri, kemik, kıkırdak ve tendonlarda hücre dışı matriksin çekme gücünü sağlayan liflerin ana proteinidir ve memelilerde en bol bulunan proteindir.'),
  ('Bitkilerde ikincil hücre duvarı nerede ve ne zaman oluşur?', 'Büyüme bitince, birincil duvar ile zar arasında', ['Hücre bölünürken, iki yavru hücrenin tam ortasındaki hücre plağında', 'Birincil duvarın dış yüzünde, hücre büyürken', 'Yalnızca kök ucundaki bölünen hücrelerde'], 'İkincil duvar, büyümesini tamamlamış hücrelerde birincil duvarın iç yüzüne, yani zar tarafına eklenir; daha kalın ve serttir.'),
  ('Ağacın odununa sertlik ve basınca dayanıklılık kazandıran, ikincil hücre duvarlarında selüloz lifleri arasına çöken ve suyu geçirmeyen polimer hangisidir?', 'Lignin', ['Pektin', 'Nişasta', 'Kitin'], 'Lignin, ksilem ve sklerenkima hücrelerinin ikincil duvarlarına çökerek duvarı sertleştirir ve su geçirmez hâle getirir.'),
  ('Meyvelerden elde edilip reçel ve marmelatların jelleşmesini sağlamak için kullanılan madde, bitki hücre duvarının hangi bileşenidir?', 'Pektin', ['Selüloz', 'Lignin', 'Suberin'], 'Pektinler özellikle orta lamelde ve birincil duvarda bol bulunan, su tutup jel oluşturabilen polisakkaritlerdir.'),
  ('Ağaç kabuğundaki mantar hücrelerinin çeperlerine çökerek su ve gaz geçişini büyük ölçüde engelleyen yağımsı madde hangisidir?', 'Suberin', ['Pektin', 'Hemiselüloz', 'Selüloz'], 'Mantar dokusu hücrelerinin çeperleri suberinle kaplanır; bu hücreler ölür ve gövdeyi su kaybına ve mikroplara karşı koruyan bir tabaka oluşturur.'),
  ('Bir bitki dokusu selüloz ve pektini parçalayan enzimlerle muamele edildiğinde duvarı tamamen uzaklaştırılmış, yalnız zarla çevrili hücreler elde ediliyor. Bu hücrelerin patlamaması için deney hangi ortamda yapılmalıdır?', 'İzotonik bir çözeltide', ['Saf suda', 'Musluk suyunda', 'Kurutulmuş havada'], 'Duvarsız bitki hücresi (protoplast) turgora karşı koruma taşımaz; hipotonik ortamda su alıp patlar. Bu yüzden osmotik dengeyi sağlayan çözeltilerde tutulur.'),
  ('Mantarların hücre duvarının temel yapısal polisakkariti ile böceklerin dış iskeletindeki ana polisakkarit aynı maddedir. Bu madde hangisidir?', 'Kitin', ['Selüloz', 'Peptidoglikan', 'Glikojen'], 'Kitin, azot içeren bir glikoz türevinin (N-asetilglikozamin) polimeridir ve hem mantar çeperinde hem eklembacaklı dış iskeletinde bulunur.'),
  ('Sıcak ve soğuk su dolu iki bardağa aynı anda birer damla mürekkep damlatıldığında mürekkebin sıcak suda daha hızlı dağıldığı görülür. Bunun nedeni nedir?', 'Moleküllerin kinetik enerjisinin artması', ['Sıcak suda derişim farkının ortadan kalkması', 'Mürekkebin sıcak suda kimyasal olarak parçalanıp küçülmesi', 'Soğuk suyun mürekkep moleküllerini itmesi'], 'Sıcaklık molekül hareketlerini hızlandırır; bu yüzden aynı derişim farkında difüzyon sıcak ortamda daha hızlı gerçekleşir.'),
  ('İçinde glikoz ve nişasta karışımı bulunan bir diyaliz torbası saf suya konuyor. Bir saat sonra torbanın dışındaki sudan alınan örnekte hangi sonuç beklenir?', 'Glikoz bulunur, nişasta bulunmaz', ['Nişasta bulunur, glikoz bulunmaz', 'İkisi de bulunur', 'Yalnızca su molekülleri bulunur'], 'Diyaliz zarının gözenekleri küçük glikoz moleküllerini geçirir, büyük polisakkarit olan nişastayı geçirmez. Glikoz derişim farkı yönünde dışarı difüzyon yapar.'),
  ('Bir zarda basit difüzyonun hızı ile ilgili olarak aşağıdaki değişikliklerden hangisi hızı azaltır?', 'Zarın kalınlaşması', ['Zar yüzey alanının artması', 'Derişim farkının artması', 'Sıcaklığın artması'], 'Fick yasasına göre difüzyon hızı yüzey alanı ve derişim farkıyla doğru, zarın kalınlığıyla ters orantılıdır; kalın zar geçişi yavaşlatır.'),
  ('Aynı sıcaklıkta ve aynı derişim farkında, küçük kütleli bir gaz molekülü ile büyük kütleli bir gaz molekülünün difüzyon hızları karşılaştırıldığında hangisi doğrudur?', 'Hafif molekül daha hızlı difüzyon yapar', ['Ağır molekül daha hızlı difüzyon yapar', 'İkisi her zaman aynı hızda yayılır', 'Gaz moleküllerinin kütlesi difüzyon hızını hiç etkilemez'], 'Aynı sıcaklıkta moleküllerin ortalama kinetik enerjileri eşittir; bu nedenle kütlesi küçük olan molekül daha hızlı hareket eder ve daha hızlı yayılır.'),
  ('Zarın iki yanındaki elektrik potansiyeli değiştiğinde açılıp kapanan kanallara ne ad verilir?', 'Voltaj kapılı kanallar', ['Ligand kapılı kanallar', 'Mekanik kapılı kanallar', 'Sürekli açık sızıntı kanalları'], 'Voltaj kapılı kanallar zar potansiyelindeki değişimi algılayan yüklü bölgeler taşır; potansiyel değişince biçim değiştirip açılır ya da kapanır.'),
  ('Bir kanal proteininin ancak belirli bir kimyasal sinyal molekülü ona bağlandığında açılması onu hangi gruba sokar?', 'Ligand kapılı kanallar', ['Voltaj kapılı kanallar', 'Akuaporinler', 'Sürekli açık sızıntı kanalları'], 'Ligand kapılı kanallarda kanalın açılması, sinyal molekülünün (ligand) kanal üzerindeki bağlanma bölgesine tutunmasına bağlıdır.'),
  ('Dokunma ve işitme reseptör hücrelerinde zarın gerilmesi ya da bükülmesiyle açılan kanallar hangi türdendir?', 'Mekanik kapılı kanallar', ['Ligand kapılı kanallar', 'Voltaj kapılı kanallar', 'Yalnızca ATP ile açılan kanallar'], 'Mekanik kapılı kanallar zardaki gerilim ya da çekme kuvvetiyle açılır; böylece fiziksel uyarılar elektrik sinyaline dönüştürülür.'),
  ('Bir taşıyıcı proteinin aynı anda yalnız tek bir maddeyi tek bir yönde taşımasına ne ad verilir?', 'Uniport', ['Simport', 'Antiport', 'Ekzositoz ile taşıma'], 'Uniport tek maddeyi taşır (örneğin GLUT glikoz taşıyıcıları); simport iki maddeyi aynı yönde, antiport ise iki maddeyi zıt yönlerde taşır.'),
  ('Bir taşıyıcı protein bir iyonu hücre içine alırken aynı döngüde başka bir iyonu hücre dışına çıkarıyor. Bu taşıma biçimi hangisidir?', 'Antiport', ['Simport', 'Uniport', 'Pinositoz'], 'İki maddenin zıt yönlerde birlikte taşınmasına antiport (karşı taşıma) denir; Na⁺/Ca²⁺ değiştiricisi buna örnektir.'),
  ('Kolaylaştırılmış difüzyonla taşınan bir madde için, derişim farkının yönü tersine çevrildiğinde ne beklenir?', 'Net taşıma yönü de tersine döner', ['Taşıma tamamen durur ve hiç başlamaz', 'Taşıyıcı ATP harcamaya başlar', 'Madde yine aynı yönde taşınmaya devam eder'], 'Kolaylaştırılmış difüzyon pasiftir; taşıyıcı iki yönde de çalışabilir ve net hareket her zaman derişimin yüksek olduğu taraftan düşük olduğu tarafa doğrudur.'),
  ('Hastanelerde damar yoluyla verilen ve kanla izotonik kabul edilen "serum fizyolojik" çözeltisi kütlece yaklaşık yüzde kaç NaCl içerir?', '%0,9', ['%9', '%0,09', '%3,5'], '%0,9\'luk NaCl çözeltisi insan kanıyla yaklaşık aynı osmotik derişime sahiptir; %3,5 ise deniz suyunun ortalama tuzluluğuna yakındır.'),
  ('Alyuvarların hipotonik ortamda su alıp patlayarak hemoglobinin ortama yayılmasına ne ad verilir?', 'Hemoliz', ['Krenasyon', 'Plazmoliz', 'Pinositoz'], 'Hemoliz alyuvar zarının yırtılmasıdır; hipotonik çözeltide su alan alyuvarlar bu nedenle parçalanır ve çözelti kırmızımsı ve saydam görünür.'),
  ('Hipertonik bir tuz çözeltisine konan alyuvarların su kaybedip yüzeyleri dikensi çıkıntılı bir görünüm alacak biçimde büzüşmesine ne ad verilir?', 'Krenasyon', ['Hemoliz', 'Deplazmoliz', 'Turgor'], 'Krenasyon, hayvan hücrelerinin hipertonik ortamda su kaybederek büzüşmesidir. Bitki hücrelerinde benzer su kaybı plazmoliz olarak adlandırılır.'),
  ('Kan örneğine yanlışlıkla saf su eklenen bir laboratuvar tüpünde birkaç dakika sonra çözeltinin bulanıklığını yitirip saydam kırmızıya döndüğü görülüyor. Bu gözlemin açıklaması hangisidir?', 'Alyuvarların patlayıp hemoglobinin çözeltiye geçmesi', ['Alyuvarların büzüşüp dibe çökmesi', 'Hemoglobinin suyla tepkimeye girip renklenmesi', 'Akyuvarların alyuvarları yutması'], 'Sağlam alyuvarlar ışığı saçarak çözeltiyi bulanık gösterir. Saf suda patlayan hücrelerden çıkan hemoglobin çözündüğü için çözelti saydamlaşır.'),
  ('Su potansiyeli Ψ = Ψs + Ψp ile hesaplanır. Çözünen potansiyeli −0,8 MPa ve basınç potansiyeli +0,3 MPa olan bir bitki hücresinin su potansiyeli kaçtır?', '−0,5 MPa', ['−1,1 MPa', '+0,5 MPa', '−0,24 MPa'], 'Ψ = −0,8 + 0,3 = −0,5 MPa. Çözünen potansiyeli her zaman sıfır ya da negatif, turgorlu hücrede basınç potansiyeli ise pozitiftir.'),
  ('Su potansiyeli −0,5 MPa olan bir bitki hücresi, su potansiyeli −0,9 MPa olan bir çözeltiye konuyor. Ne olur?', 'Hücre su kaybeder', ['Hücre su alır', 'Su alışverişi olmaz', 'Hücre duvarı çözünür'], 'Su, su potansiyelinin yüksek olduğu yerden düşük olduğu yere hareket eder. −0,5, −0,9\'dan yüksek olduğu için su hücreden çözeltiye geçer.'),
  ('Saf suyun standart koşullardaki su potansiyeli kaç kabul edilir?', '0 MPa', ['−1 MPa', '+1 MPa', '−0,25 MPa'], 'Saf suyun su potansiyeli sıfır kabul edilir; içine madde çözündükçe su potansiyeli düşer ve negatif değerler alır.'),
  ('Hipertonik bir çözeltiye konan bir bitki hücresinde, sitoplazmanın su kaybederek büzülmesi ve zarın hücre duvarından ayrılmasına ne ad verilir?', 'Plazmoliz', ['Hemoliz', 'Turgor', 'Deplazmoliz'], 'Plazmolizde koful ve sitoplazma su kaybeder; hücre zarı çeperden ayrılır ancak sağlam duvar hücrenin genel biçimini korur.'),
  ('Plazmoliz geçirmiş bir soğan epidermis hücresi yeniden saf suya alındığında zarın tekrar çepere yaslanmasına ne ad verilir ve bu olay neyi gösterir?', 'Deplazmoliz; hücrenin canlı ve zarının sağlam olduğunu', ['Hemoliz; hücrenin öldüğünü', 'Krenasyon; zarın yırtıldığını', 'Turgorun kalıcı olarak yitirildiğini'], 'Deplazmolizde hücre osmozla su alıp eski hâline döner. Bu ancak seçici geçirgenliğini koruyan canlı bir zar varsa olur; ölü hücre plazmoliz-deplazmoliz göstermez.'),
  ('Bitki ve mantar hücrelerinde, hayvan hücrelerindeki Na⁺/K⁺ pompasının yerine zar boyunca temel iyon farkını oluşturan birincil pompa hangisidir?', 'H⁺ pompası', ['Na⁺/Ca²⁺ değiştiricisi', 'Akuaporin', 'Glikoz uniportu'], 'Bitki ve mantarlarda zardaki H⁺-ATPaz protonları dışarı pompalar; oluşan proton farkı ve zar potansiyeli pek çok maddenin ikincil aktif taşınmasında kullanılır.'),
  ('Mide asidinin aşırı salgılandığı durumlarda kullanılan "proton pompası inhibitörü" ilaçlar hangi taşıma mekanizmasını hedef alır?', 'Mide hücrelerindeki H⁺/K⁺-ATPazı', ['Mide hücrelerinin su kanallarını', 'Mide hücrelerine glikoz alan uniportu', 'Mide hücrelerinde besinlerin endositozla alınmasını sağlayan zar keseciklerini'], 'Mide salgı hücrelerindeki H⁺/K⁺-ATPaz, H⁺ iyonlarını derişim farkına karşı mide boşluğuna pompalar; bu pompanın baskılanması asit salgısını azaltır.'),
  ('Ağızdan verilen sıvı tedavisinde (ORS) suya tuzla birlikte bir miktar glikoz da eklenmesinin hücresel gerekçesi nedir?', 'Glikozun Na⁺ ve suyun emilimini artırması', ['Glikozun bağırsakta tuzu parçalaması', 'Glikozun ishale yol açan bakterileri bağırsakta doğrudan öldürmesi', 'Glikozun bağırsak zarını kalınlaştırması'], 'Bağırsak hücrelerindeki Na⁺-glikoz ortak taşıyıcısı ikisini birlikte içeri alır; hücreye giren çözünenler suyu da osmozla peşinden çeker. Bu mekanizma ishalde de çoğunlukla çalışmayı sürdürür.'),
  ('Hücreler demiri kandaki transferrin proteinine bağlı olarak alır. Transferrin önce zardaki özel reseptörüne bağlanır, sonra kesecikle hücre içine alınır. Bu alım hangi taşıma biçimidir?', 'Reseptör aracılı endositoz', ['Fagositoz', 'Basit difüzyon', 'Taşıyıcıyla kolaylaştırılmış difüzyon'], 'Belirli bir molekülün önce zardaki özgül reseptöre bağlanıp ardından kesecikle alınması reseptör aracılı endositozdur; bu yolla seyrek bulunan maddeler bile verimli biçimde toplanır.'),
  ('Bir amip bir bakteriyi yalancı ayaklarıyla sarıp yuttuktan sonra bakterinin sindirilmesi hücrede hangi sırayla gerçekleşir?', 'Besin kofulu lizozomla kaynaşıp sindirilir', ['Bakteri doğrudan çekirdeğe taşınır ve orada DNA\'sı parçalanarak sindirilir', 'Bakteri mitokondriye girip yakılır', 'Bakteri Golgi\'de paketlenip hücre dışına atılır'], 'Fagositozla oluşan besin kofulu (fagozom) lizozomlarla birleşir; lizozomun hidrolitik enzimleri bakteriyi parçalar ve yararlı yapı taşları sitoplazmaya geçer.'),
  ('Hücrelerin sürekli ve herhangi bir dış sinyale gerek duymadan bazı maddeleri (örneğin hücre dışı matriks bileşenlerini) ekzositozla salmasına ne ad verilir?', 'Sürekli salgılama', ['Düzenlenmiş salgılama', 'Fagositoz', 'Reseptör aracılı endositoz'], 'Sürekli salgılamada Golgi\'den çıkan kesecikler kesintisiz olarak zarla kaynaşır. Düzenlenmiş salgılamada ise kesecikler hücrede bekletilir ve ancak bir sinyal geldiğinde boşaltılır.'),
  ('Bitki hücrelerinde hücre duvarının hemiselüloz ve pektin bileşenleri hücre dışına hangi yolla ulaştırılır?', 'Ekzositozla', ['Doğrudan difüzyonla', 'Zardaki kanal proteinlerinden geçerek', 'Fagositozla'], 'Hemiselüloz ve pektin Golgi\'de yapılıp keseciklere paketlenir; kesecikler zarla kaynaşınca içerikleri duvarın yapılacağı yere boşaltılır.'),
  ('Çekirdek zarının iç yüzünü bir ağ gibi döşeyerek çekirdeğe biçim ve mekanik destek veren, ara filament ailesinden proteinlere ne ad verilir?', 'Laminler', ['Aktinler', 'Tübülinler', 'Histonlar'], 'Laminler çekirdek laminasını oluşturur; çekirdeğin biçimini korur ve kromatinin bazı bölgelerinin zara tutunmasını sağlar.'),
  ('Hücrede histon proteinleri nerede sentezlenir ve DNA\'ya nasıl ulaşır?', 'Sitoplazmada yapılır, porlardan çekirdeğe alınır', ['Çekirdekçikte; hiç taşınmadan yerinde kalarak', 'Mitokondride; çekirdek zarıyla kaynaşarak', 'Golgi\'de yapılır, salgı kesecikleriyle çekirdek zarına boşaltılarak çekirdeğe girer'], 'Bütün proteinler gibi histonlar da sitoplazmadaki ribozomlarda yapılır. Taşıdıkları çekirdek yerleşim sinyali sayesinde porlardan çekirdeğe aktarılırlar.'),
  ('Bir sitoplazma proteininin genine çekirdek yerleşim sinyali kodlayan kısa bir dizi eklendiğinde, bu proteinin hücredeki yeri nasıl değişir?', 'Çekirdekte birikir', ['Hücre dışına salgılanır', 'Mitokondriye girer', 'Lizozomda yıkılır'], 'Bu deney türleri, proteinin gideceği yeri kendi amino asit dizisindeki sinyallerin belirlediğini göstermiştir; sinyal eklenince protein çekirdeğe taşınır.'),
  ('Hiçbir hedefleme sinyali taşımayan bir protein serbest ribozomlarda sentezlendikten sonra genellikle nerede kalır?', 'Sitoplazmanın sıvı kısmında', ['Hücre dışında', 'Lizozomun içinde', 'Endoplazmik retikulumun iç boşluğunda'], 'Hedefleme sinyali olmayan proteinler sentezlendikleri sitoplazmada kalır; organellere ya da hücre dışına gitmek için özel sinyal dizileri gerekir.'),
  ('Ökaryot hücrelerin sitoplazmasındaki ribozomların alt birimleri hangisinde doğru verilmiştir?', '40S ve 60S', ['30S ve 50S', '20S ve 60S', '30S ve 60S\'nin yarısı'], 'Ökaryot sitoplazmik ribozomu 80S\'dir; 40S küçük ve 60S büyük alt birimden oluşur. Bakteri ribozomu ise 30S ve 50S alt birimli 70S\'dir.'),
  ('Salgı proteinleri ER\'nin iç boşluğuna girdikten sonra uçlarındaki sinyal dizisi ne olur?', 'Sinyal peptidazla kesilir', ['Protein Golgi\'den çıkana kadar korunur', 'Proteinin hücre zarına çapası olur', 'DNA\'ya geri bağlanır'], 'Sinyal dizisi görevini tamamladıktan sonra ER zarındaki sinyal peptidaz enzimiyle kesilir; bu yüzden olgun salgı proteinleri bu diziyi taşımaz.'),
  ('Hücredeki bütün zar sistemleri için gereken fosfolipitlerin büyük kısmı hangi organelde sentezlenir?', 'Düz ER\'de', ['Çekirdekçikte, rRNA ile birlikte', 'Lizozomda', 'Sentrozomda'], 'Zar fosfolipitleri ve kolesterol esas olarak düz ER zarında yapılır; buradan keseciklerle ya da lipit taşıyıcı proteinlerle öteki zarlara dağıtılır.'),
  ('Golgi cisimciğinde proteinlere eklenen değişiklikler arasında aşağıdakilerden hangisi yer alır?', 'Şeker zincirlerinin düzenlenmesi', ['Peptit bağlarının ilk kez kurulması', 'DNA\'nın eşlenmesi', 'ATP sentezlenmesi'], 'Golgi\'de ER\'den gelen şeker zincirleri budanır ya da yeni şekerler eklenir, bazı proteinlere sülfat ya da fosfat grupları bağlanır; peptit bağları ise ribozomda kurulur.'),
  ('Bağırsak ve solunum yolu epitelindeki goblet hücreleri koyu kıvamlı mukus salgılar. Mukustaki glikoproteinlerin yoğun şeker zincirleri bu hücrelerde en çok hangi organelde eklenir?', 'Golgi cisimciği', ['Mitokondri', 'Peroksizom', 'Kloroplast'], 'Mukus glikoproteinlerine eklenen çok sayıda şeker zinciri büyük ölçüde Golgi\'de bağlanır; bu yüzden goblet hücrelerinde Golgi çok gelişmiştir.'),
  ('Hücrede ilk oluşan (birincil) lizozomlar hangi organelden tomurcuklanarak ayrılır?', 'Golgi\'nin trans yüzünden', ['Mitokondrinin dış zarından', 'Çekirdekçikten', 'Kloroplast iç zarından ve tilakoitlerinden'], 'Lizozom enzimleri granüllü ER\'de yapılıp Golgi\'de işaretlenir ve trans Golgi\'den kopan keseciklerle lizozom bölmesine ulaştırılır.'),
  ('Gaucher hastalığı gibi bazı lizozomal depo hastalıklarında hastaya damar yoluyla eksik enzim verilerek tedavi yapılır. Kana verilen enzimin hücrelerin lizozomlarına ulaşmasını sağlayan süreç hangisidir?', 'Reseptör aracılı endositoz', ['Basit difüzyon', 'Ekzositoz', 'Kanal proteinlerinden serbest geçiş'], 'Tedavi enzimleri hücre yüzeyindeki reseptörlere bağlanır, kesecikle içeri alınır ve endozom yoluyla lizozomlara iletilir.'),
  ('Bir lizozomun içindeki maddeler sindirildikten sonra kalan ve sindirilemeyen artıkları taşıyan keseciğe ne ad verilir?', 'Kalıntı cisimcik', ['Birincil lizozom', 'Salgı keseciği', 'Endoplazmik retikulum'], 'Sindirim tamamlandığında sindirilemeyen maddeler kalıntı cisimcikte kalır; bunlar ekzositozla dışarı atılabilir ya da hücrede birikebilir.'),
  ('Bitki hücrelerinde hayvan hücrelerindeki lizozomların sindirim işlevini büyük ölçüde hangi yapı üstlenir?', 'Merkezi koful', ['Kloroplastın nişasta depolayan stroması', 'Hücre duvarı', 'Plazmodezmata'], 'Bitkilerin merkezi kofulu asidiktir ve hidrolitik enzimler taşır; yıpranmış organellerin yıkımı gibi lizozoma benzer işlevler görür.'),
  ('Besinsiz bırakılan maya hücrelerinde otofajinin belirgin biçimde arttığı gözleniyor. Bu yanıtın hücreye sağladığı yarar nedir?', 'Açlıkta yapı taşı ve enerji sağlamak', ['Hücre duvarını kalınlaştırıp dış ortamdan daha fazla besin emmek', 'Hücreyi hemen bölünmeye zorlamak', 'Çekirdeği sindirip DNA miktarını artırmak'], 'Açlıkta hücre gereksiz bileşenlerini otofajiyle parçalar; açığa çıkan amino asit, şeker ve yağ asitleri temel işlevleri sürdürmekte kullanılır.'),
  ('Hücre dışından alınan maddelerin lizozomlarda sindirilmesi ile hücrenin kendi yapılarını lizozomlarda sindirmesi sırasıyla nasıl adlandırılır?', 'Heterofaji ve otofaji', ['Otofaji ve heterofaji', 'Ekzositoz ve pinositoz', 'Apoptoz ve nekroz'], 'Heterofajide madde fagositoz ya da endositozla dışarıdan alınır; otofajide ise sindirilen malzeme hücrenin kendi organelleri ya da sitoplazmasıdır.'),
  ('Hasar görmüş mitokondrilerin seçici olarak otofajiyle ortadan kaldırılmasına ne ad verilir?', 'Mitofaji', ['Mitoz', 'Fagositoz', 'Pinositoz'], 'Mitofaji, işlevini yitirmiş mitokondrilerin otofagozomlarla sarılıp lizozomlarda yıkılmasıdır; zararlı reaktif oksijen türlerinin birikmesini önler.'),
  ('Peroksizomlarda yağ asitleri ve başka maddeler oksitlenirken zararlı bir yan ürün oluşur, ardından aynı organelde etkisizleştirilir. Bu yan ürün hangisidir?', 'Hidrojen peroksit', ['Karbon monoksit', 'Amonyak', 'Laktik asit'], 'Peroksizomlardaki oksidaz enzimleri maddelerden aldıkları hidrojenleri oksijene aktararak H₂O₂ oluşturur; katalaz da bu maddeyi su ve oksijene ayrıştırır.'),
  ('Yağlı tohumlar (örneğin ayçiçeği) çimlenirken tohumda depolanan yağların şekere dönüştürülmesini sağlayan özelleşmiş peroksizomlara ne ad verilir?', 'Glioksizom', ['Lizozom', 'Amiloplast', 'Kromoplast'], 'Glioksizomlar yağ asitlerini yıkıp glioksilat döngüsüyle şeker yapımına uygun ara ürünlere çevirir; fotosentez başlayana kadar fide bu şekerlerle beslenir.'),
  ('Bitki hücrelerinde merkezi kofulu sitoplazmadan ayıran zara ne ad verilir?', 'Tonoplast', ['Plazmalemma', 'Tilakoit zarı', 'Orta lamel'], 'Tonoplast kofulun seçici geçirgen zarıdır; üzerindeki pompa ve kanallar iyonların, şekerlerin ve suyun kofula giriş çıkışını düzenler.'),
  ('Tütün bitkisinin hücrelerinde yapılan nikotin gibi zehirli savunma maddeleri, bitkinin kendi metabolizmasına zarar vermeyecek biçimde çoğunlukla nerede saklanır?', 'Merkezi kofulda', ['Çekirdekçikte', 'Mitokondri matriksinde', 'Kloroplast stromasında'], 'Alkaloitler ve tanenler gibi zehirli ikincil maddeler tonoplastla ayrılmış kofulda biriktirilir; böylece sitoplazmadaki tepkimeleri etkilemezler ama otçullar yaprağı çiğneyince açığa çıkarlar.'),
  ('Limon suyunun ekşi tadını veren sitrik asit, limon hücrelerinin hangi bölümünde yoğun olarak bulunur?', 'Merkezi kofulun özsuyunda', ['Hücre duvarında', 'Mitokondri zarında', 'Çekirdek sıvısında'], 'Bitki kofulları genellikle asidiktir ve organik asitler depolar; turunçgillerin meyve hücrelerinde koful özsuyu çok yüksek derişimde sitrik asit içerir.'),
  ('Bitki hücrelerinin büyürken sitoplazma miktarını pek artırmadan hacimlerini hızla büyütebilmesi büyük ölçüde neye bağlıdır?', 'Kofulun su alarak genişlemesine', ['Çekirdeğin büyümesine', 'Mitokondri sayısının artmasına', 'Hücre duvarının incelmesine'], 'Hücre büyümesinin büyük kısmı kofulun su alıp genişlemesiyle olur; bu, yeni sitoplazma yapmaya göre çok daha az enerji ve madde gerektirir.'),
  ('Tatlı suda yaşayan bir amip, tuz derişimi yavaş yavaş artırılan sulara aktarıldığında kontraktil kofulunun boşalma sıklığı nasıl değişir?', 'Azalır', ['Artar', 'Değişmez', 'Önce durur, sonra iki katına çıkar'], 'Ortam tuzlulaştıkça hücre ile ortam arasındaki osmotik fark azalır, hücreye giren su miktarı düşer; atılacak su azaldığı için koful daha seyrek boşalır.'),
  ('Genç bir bitki hücresinde çok sayıda küçük koful bulunurken aynı hücre olgunlaştığında tek ve büyük bir merkezi koful görülmesi nasıl açıklanır?', 'Küçük kofulların büyüyüp birbiriyle kaynaşması', ['Küçük kofulların sindirilip yerine yenisinin yapılması', 'Çekirdeğin kofula dönüşmesi', 'Hücre duvarının içeri çökerek koful oluşturması'], 'Hücre olgunlaştıkça küçük kofullar su alıp büyür ve zarlarını kaynaştırarak birleşir; sonunda hacmin büyük kısmını kaplayan tek bir merkezi koful oluşur.'),
  ('Hücre hiç bölünmese bile mitokondri sayısı enerji gereksinimine göre artabilir. Yeni mitokondriler nasıl oluşur?', 'Var olan mitokondrilerin büyüyüp bölünmesiyle', ['Golgi keseciklerinin kaynaşmasıyla', 'Çekirdek zarından tomurcuklanmayla', 'Sitoplazmada sıfırdan kendiliğinden kurulmayla'], 'Mitokondriler ancak var olan mitokondrilerin bölünmesiyle çoğalır; hücre mitokondrilerini tümüyle yitirirse yeniden yapamaz.'),
  ('Mitokondri DNA\'sındaki mutasyonlardan kaynaklanan hastalıklar en çok hangi dokularda belirti verir?', 'Beyin ve kas dokusunda', ['Yalnızca deride', 'Yağ dokusunda ve kemik iliğinde', 'Yalnız saç ve tırnak köklerinde'], 'Mitokondri DNA\'sı solunum zinciri proteinlerini şifrelediğinden bozukluklar ATP üretimini azaltır; en çok etkilenenler sinir, kas ve göz gibi yoğun enerji kullanan dokulardır.'),
  ('Kloroplastta tilakoitlerin üst üste dizilerek oluşturduğu madeni para yığınına benzeyen yapılara ne ad verilir?', 'Granum', ['Krista', 'Stroma', 'Matriks'], 'Tilakoitler yığınlar hâlinde dizilerek granumları (çoğulu grana) oluşturur; komşu granumlar stroma lamelleriyle birbirine bağlanır.'),
  ('Kloroplastın kendi DNA\'sı, ribozomları ve fotosentezle yapılan geçici nişasta tanecikleri organelin hangi bölümünde bulunur?', 'Stromada', ['Tilakoit içinde', 'Dış zarda', 'Zarlar arası boşlukta'], 'Stroma kloroplastın sıvı iç kısmıdır; halkasal DNA, 70S ribozomlar, enzimler ve nişasta tanecikleri burada yer alır.'),
  ('Domates olgunlaşırken yeşilden kırmızıya dönmesi hücre düzeyinde hangi olayla açıklanır?', 'Kromoplastların oluşması', ['Kofula kırmızı antosiyanin dolması', 'Mitokondrilerin kırmızıya boyanması', 'Hücre duvarının renk değiştirmesi'], 'Olgunlaşmada klorofil yıkılır ve tilakoitler dağılır; plastitler kırmızı likopen ve diğer karotenoitleri biriktiren kromoplastlara dönüşür.'),
  ('Havucun turuncu rengini veren beta karoten, havuç kökünün hücrelerinde hangi yapıda birikir?', 'Kromoplastlarda', ['Kloroplastlarda', 'Merkezi kofulda', 'Hücre duvarında'], 'Karotenoitler suda çözünmeyen pigmentlerdir ve kromoplastlarda birikir; kırmızı lahanadaki suda çözünen antosiyaninler ise kofulda bulunur.'),
  ('Mikrotübüllerin yapı birimi hangisidir?', 'Tübülin dimerleri', ['Aktin monomerleri', 'Keratin lifleri', 'Konneksin altılıları ve kaderinler'], 'Mikrotübüller alfa ve beta tübülinden oluşan dimerlerin uç uca eklenip içi boş bir tüp oluşturmasıyla kurulur.'),
  ('Bir amibe sitokalasin adlı, aktin ipliklerinin uzamasını engelleyen bir madde verildiğinde hangisi beklenir?', 'Hareketinin durması', ['Kontraktil kofulun boşalmasının hızlanması', 'Çekirdeğin ikiye bölünmesi', 'Kamçı oluşturup yüzmeye başlaması'], 'Yalancı ayak, aktin ipliklerinin hücrenin ön ucunda hızla uzamasıyla oluşur; aktin kurulumu engellenince amip hareket edemez.'),
  ('Su yosunu (Elodea) yaprak hücreleri mikroskopta incelenirken kloroplastların hücre çeperi boyunca sürekli döndüğü görülür. Bu sitoplazma akıntısını sağlayan yapılar hangileridir?', 'Aktin iplikleri ve miyozin', ['Mikrotübüller ve sentriyoller', 'Ara filamentler ve laminler', 'Hücre duvarı ve orta lamel'], 'Sitoplazma akıntısında miyozin motorları aktin ipliklerinin üzerinde yürüyerek organelleri ve sitoplazmayı sürükler; bu, büyük bitki hücrelerinde madde dağılımını hızlandırır.'),
  ('Deri epitel hücrelerinde, saçta ve tırnaklarda bol bulunan ara filament proteini hangisidir?', 'Keratin', ['Vimentin', 'Tübülin', 'Lamin'], 'Keratinler epitel hücrelerine özgü ara filamentleri oluşturur; ölü keratinize hücreler saç, tırnak ve derinin en dış katmanını meydana getirir.'),
  ('Motor proteinlerin bir hücre iskeleti ipliği üzerinde adım adım ilerleyebilmesi için gereken enerjiyi sağlayan olay hangisidir?', 'ATP\'nin hidrolizi', ['Glikozun hücre dışına atılması', 'Osmozla su girişi', 'DNA\'nın eşlenmesi'], 'Motor proteinlerin "baş" bölgeleri ATP\'yi parçalar; açığa çıkan enerjiyle biçim değiştirerek iplik üzerinde yürür.'),
  ('Mikrotübül üzerinde değil, aktin iplikleri üzerinde hareket eden motor protein ailesi hangisidir?', 'Miyozinler', ['Kinezinler', 'Dineinler', 'Tübülinler'], 'Miyozin aileleri aktin iplikleri üzerinde çalışır; kas kasılmasının yanı sıra keseciklerin aktin ağında taşınmasında ve sitoplazma akıntısında da görev yapar.'),
  ('Sil ve kamçıların tabanında bulunan, onları hücreye bağlayan ve yapıca sentriyole benzeyen yapıya ne ad verilir?', 'Bazal cisim', ['Sentromer', 'Çekirdekçik', 'Desmozom'], 'Bazal cisimler dokuz üçlü mikrotübülden oluşur; sentriyollerden köken alır ve silin iç iskeletinin büyümesi için temel görevi görür.'),
  ('Bakterilerin yüzeyinde bulunan, kamçıdan daha kısa ve çok sayıda olan, bakterinin konak dokulara ve yüzeylere tutunmasını sağlayan ince protein uzantılarına ne ad verilir?', 'Fimbriya', ['Mezozom', 'Kapsül', 'Nükleoit'], 'Fimbriyalar hareket için değil tutunma için kullanılır; örneğin bazı bakterilerin idrar yolu epiteline yapışarak enfeksiyon başlatmasında rol oynar.'),
  ('Bakterilerde zarla çevrili olmayan, ana kromozomun sitoplazmada yoğunlaşarak bulunduğu bölgeye ne ad verilir?', 'Nükleoit', ['Çekirdekçik', 'Nükleozom', 'Nükleoplazma'], 'Prokaryotlarda DNA zarla ayrılmamış olsa da sitoplazmanın belirli bir bölgesinde toplanır; bu bölgeye nükleoit denir.'),
  ('Diş yüzeyinde bakterilerin salgıladıkları yapışkan polisakkarit tabakası içinde topluluk hâlinde yaşamasıyla oluşan diş plağı hangi kavrama örnektir?', 'Biyofilm', ['Endospor', 'Plazmit', 'Nükleoit'], 'Biyofilmlerde bakteriler kendi salgıladıkları jel benzeri matrikse gömülüdür; bu yapı onları ağız gargarası ve antibiyotik gibi etkenlere karşı korur.'),
  ('Dokulara girip ölü hücreleri, bakterileri ve yabancı parçacıkları yutarak sindiren makrofajlarda en bol bulunması beklenen organel hangisidir?', 'Lizozom', ['Kloroplast', 'Kontraktil koful', 'Glioksizom'], 'Makrofajlar yuttukları maddeleri lizozom enzimleriyle sindirir; bu nedenle sitoplazmaları çok sayıda lizozom içerir.'),
  ('Bitkilerde ksilemin trake hücreleri işlev görmeye başladığında hücre içeriği için hangisi doğrudur?', 'Protoplast ölmüş, çeper kalmıştır', ['Çekirdekleri ve kloroplastları çok gelişmiş, canlı hücrelerdir', 'Çok sayıda ribozom ve mitokondri taşırlar', 'Sitoplazmaları canlı ama çekirdeksizdir'], 'Trake hücreleri olgunlaşırken programlı olarak ölür; içi boşalmış, odunlaşmış çeperleri suyun taşındığı borular olarak kalır.'),
  ('Derinin en dış katmanındaki hücreler yüzeye doğru ilerledikçe çekirdeklerini ve organellerini yitirip keratinle dolar. Bu değişikliğin sonucu nedir?', 'Su geçirmez koruyucu bir tabaka oluşur', ['Hücreler fotosentez yapmaya başlar', 'Hücreler daha hızlı bölünür', 'Deri yüzeyinde salgı bezleri çoğalır'], 'Keratinleşen hücreler ölür ve sıkıca paketlenmiş bir tabaka hâline gelir; bu katman su kaybını ve mikropların girişini engeller.'),
  ('Bir bitkinin kök hücreleri ile yaprak mezofil hücreleri karşılaştırıldığında hangisi genellikle doğrudur?', 'Kökte kloroplast yoktur, mezofilde boldur', ['Kök hücrelerinde daha çok kloroplast bulunur', 'İkisinde de hiç mitokondri yoktur', 'Yalnız kök hücreleri hücre duvarı taşır'], 'Toprak altındaki kök hücreleri ışık almadığından kloroplast taşımaz; mitokondri ise iki hücre tipinde de bulunur.'),
  ('Bir hücredeki tek bir Na⁺/K⁺ pompası bir saniyede 200 döngü tamamlıyor. Bu pompa bir saniyede hücre dışına kaç Na⁺ iyonu çıkarır?', '600', ['400', '200', '1000'], 'Her döngüde 3 Na⁺ dışarı atılır: 200 × 3 = 600 Na⁺. Aynı sürede 200 × 2 = 400 K⁺ içeri alınır.'),
  ('Na⁺/K⁺ pompası ile hücre dışına 6000 Na⁺ iyonu çıkarılması için en az kaç ATP molekülü harcanır?', '2000', ['6000', '3000', '18 000'], 'Pompa her ATP için bir döngü yapar ve her döngüde 3 Na⁺ çıkarır; 6000 / 3 = 2000 ATP gerekir.'),
  ('Hücre içi sıvının osmotik derişimi yaklaşık 300 miliosmol/L kabul edilirse, tamamen iyonlaşan NaCl\'nin kaç milimolar çözeltisi bu hücrelerle izotonik olur?', '150 mM', ['300 mM', '3000 mM', '75 mM'], 'Her NaCl iki tanecik (Na⁺ ve Cl⁻) verdiği için 150 mM × 2 = 300 miliosmol/L eder.'),
  ('Bir mikroskopta 100 kat büyütmede görüş alanının çapı 2 mm\'dir. Aynı mikroskopta 400 kat büyütmeye geçildiğinde görüş alanının çapı yaklaşık ne olur?', '0,5 mm', ['8 mm', '2 mm', '0,25 mm'], 'Büyütme 4 katına çıkınca görüş alanının çapı 4\'te 1\'ine iner: 2 mm / 4 = 0,5 mm.'),
  ('Çapı 0,5 mm olan bir görüş alanında, bir uçtan öbür uca yan yana 20 hücre sığdığı görülüyor. Bir hücrenin ortalama çapı kaç mikrometredir?', '25 µm', ['10 µm', '2,5 µm', '250 µm'], '0,5 mm = 500 µm; 500 / 20 = 25 µm.'),
  ('Bir elektron mikroskobu fotoğrafında, gerçekte 10 µm uzunluğunda olan bir yapının görüntüsü 50 mm uzunluğunda ölçülüyor. Fotoğrafın büyütmesi kaçtır?', '5000 kat', ['500 kat', '50 000 kat', '5 kat'], '50 mm = 50 000 µm; büyütme = 50 000 / 10 = 5000 kat.'),
  ('Denizde kalan birinin susuzluğunu deniz suyu içerek gideremeyip daha da kötüleşmesinin hücresel düzeydeki açıklaması nedir?', 'Deniz suyunun hipertonik olması', ['Deniz suyunun hücrelere göre hipotonik olması', 'Deniz suyunun içinde hiç serbest su molekülü bulunmaması', 'Deniz suyunun mideye girmeden emilmesi'], 'Deniz suyu vücut sıvılarından çok daha tuzludur; emilen tuz hücre dışı sıvıyı derişik hâle getirir, hücrelerden su çekilir ve tuzu atmak için daha da fazla su kaybedilir.'),
  ('Kuru nohut ya da fasulye tanelerinin suda bekletildiğinde hacimlerinin büyük ölçüde artması, osmozun yanı sıra en çok hangi olaya bağlıdır?', 'Kolloidlerin su çekmesi', ['Tohumun fotosentez yapıp su üretmesi', 'Tohumun aktif taşımayla tuz pompalaması', 'Su moleküllerinin tohumda kimyasal olarak yeniden sentezlenmesi'], 'İmbibisyonda selüloz, nişasta ve proteinler gibi su seven kolloidler suyu yüzeylerine çekerek şişer; bu olay ölü tohumlarda bile görülebilir.'),
  ('Burun tıkanıklığında kullanılan hipertonik tuzlu su spreylerinin şişmiş burun mukozasını rahatlatmasının nedeni hangisidir?', 'Dokudaki suyu osmozla çekmesi', ['Mukoza hücrelerine su pompalaması', 'Burun kıllarını eritmesi', 'Burundaki sinir uçlarını uyuşturarak tıkanıklık hissini gidermesi'], 'Hipertonik çözelti mukozanın yüzeyine sürüldüğünde dokudaki fazla sıvı osmozla dışarı çekilir; şişlik azalır ve mukus incelir.'),
  ('Sabunla en az 20 saniye el yıkamanın grip ve koronavirüs gibi zarflı virüsleri etkisiz bırakmasının nedeni nedir?', 'Lipit zarfın parçalanması', ['Sabunun virüsün DNA\'sını eşlemesi', 'Sabunun virüsleri besin olarak kullanıp sindirmesi', 'Sabunun virüse antikor bağlaması'], 'Sabun molekülleri amfipatiktir; lipit zarfın içine girip onu misellere ayırır. Zarfı dağılan virüs hücrelere tutunamaz.'),
  ('Bazı yılanların zehrinde bulunan fosfolipaz enzimleri alyuvarların parçalanmasına (hemolize) yol açar. Bu enzimin hedefi hangisidir?', 'Zar fosfolipitleri', ['Hücre içindeki DNA', 'Mitokondrideki 70S ribozomlar', 'Hemoglobindeki demir'], 'Fosfolipazlar zar fosfolipitlerinin bağlarını kopararak lipit çift katmanının bütünlüğünü bozar; zarı zayıflayan alyuvarlar patlar.'),
  ('Bitkilerde suyun ve çözünmüş maddelerin hücre duvarları ve hücreler arası boşluklar boyunca, hiçbir zardan geçmeden ilerlediği yola ne ad verilir?', 'Apoplast yolu', ['Simplast yolu', 'Plazmoliz yolu', 'Floem yolu'], 'Apoplast, birbirine bağlı hücre duvarları ve aradaki boşluklardan oluşan cansız ağdır. Simplast yolunda ise madde plazmodezmalarla birbirine bağlı sitoplazmalar içinden ilerler.'),
  ('Aşağıdaki organellerden hangisi tek bir zarla çevrilidir?', 'Lizozom', ['Mitokondri', 'Kloroplast', 'Çekirdek'], 'Çekirdek, mitokondri ve kloroplast çift zarlıdır; lizozom, peroksizom, Golgi ve ER gibi yapılar ise tek zarla sınırlanır.'),
  ('Ökaryot bir bitki hücresinde DNA aşağıdaki yapılardan hangisinde bulunmaz?', 'Golgi cisimciği', ['Çekirdek', 'Mitokondri', 'Kloroplast'], 'Bitki hücresinde DNA çekirdekte, mitokondride ve kloroplastta bulunur; Golgi cisimciği kalıtım maddesi taşımaz.'),
  ('Bir öğrenci "Bitki hücreleri kloroplast taşıdığı için mitokondriye ihtiyaç duymaz" diyor. Bu görüş için en doğru değerlendirme hangisidir?', 'Yanlıştır; bitki hücreleri de mitokondride solunum yapar', ['Doğrudur; bitkiler bütün ATP\'yi kloroplastta üretir', 'Doğrudur; bitki hücrelerinde mitokondri bulunmaz', 'Yanlıştır; çünkü bitkilerde kloroplast da bulunmaz'], 'Bitki hücreleri hem kloroplast hem mitokondri taşır. Köklerde ve karanlıkta kloroplastlar ATP sağlayamaz; hücrenin genel enerji gereksinimi mitokondrilerdeki solunumla karşılanır.'),
  ('Granüllü ve granülsüz endoplazmik retikulum görünüş bakımından karşılaştırıldığında hangisi doğrudur?', 'Granüllü ER yassı keseciklerden, düz ER daha çok borucuklardan oluşur', ['Düz ER\'nin yüzeyi ribozomlarla kaplıdır', 'Granüllü ER yalnızca bitki hücrelerinde bulunur', 'İkisinin de zarı çift katlıdır'], 'Granüllü ER ribozom kaplı yassı kesecik (sisterna) yığınları biçimindedir; düz ER ise ribozomsuz, dallanmış borucuklardan oluşan bir ağdır.'),
  ('Lizozoma gidecek bir sindirim enziminin sentezlendiği andan görev yerine ulaşana kadar izlediği yol hangisidir?', 'Ribozom → granüllü ER → Golgi → lizozom', ['Ribozom → sitoplazma → lizozom', 'Çekirdek → Golgi → granüllü ER → lizozom', 'Ribozom → mitokondri → peroksizom → lizozom'], 'Lizozom enzimleri salgı proteinleri gibi granüllü ER\'de yapılır, Golgi\'de mannoz-6-fosfatla işaretlenir ve keseciklerle lizozoma iletilir.'),
  ('Bir hücrede çekirdek, ribozom, granüllü ER ve Golgi\'nin birlikte çalışmasını gerektiren olay hangisidir?', 'Bir sindirim enziminin üretilip salgılanması', ['Oksijenin hücreye difüzyonla girmesi', 'Suyun akuaporinden geçmesi', 'Glikozun sitoplazmada parçalanması'], 'Salgı proteininin şifresi çekirdekteki DNA\'dan mRNA\'ya geçer; ribozomlarda granüllü ER üzerinde sentezlenir, Golgi\'de paketlenip dışarı verilir.'),
  ('Mitokondri ile kloroplastın farkı olarak hangisi doğrudur?', 'Yalnız kloroplast ışık enerjisiyle organik madde üretir', ['Yalnız mitokondri çift zarlıdır', 'Yalnız kloroplast ATP sentaz taşır', 'Yalnız mitokondri kendi DNA\'sını taşır'], 'İki organel de çift zarlıdır, kendi DNA\'sına ve ATP sentaza sahiptir. Işık enerjisini kullanıp karbondioksitten organik madde yapan yalnız kloroplasttır.'),
  ('Işık mikroskobunda 100 kat büyütmeli objektifle çalışırken lamelin üzerine bir damla özel yağ konulmasının amacı nedir?', 'Işığın kırılarak kaybolmasını önleyip ayırma gücünü artırmak', ['Preparatı mercek altında yapıştırıp sabitlemek', 'Hücreleri öldürüp boyamak', 'Merceği soğutup bozulmasını önlemek'], 'İmmersiyon yağının kırılma indisi cama yakındır; ışık havada saçılmadan objektife ulaşır ve görüntü daha net, ayrıntılı olur.'),
  ('Bir böceğin ya da çiçeğin dış yüzeyini düşük büyütmede, üç boyutlu ve kesit almadan incelemek için en uygun ışık mikroskobu türü hangisidir?', 'Stereo (diseksiyon) mikroskobu', ['Transmisyon elektron mikroskobu', 'Faz kontrast mikroskobu', 'Konfokal floresan mikroskobu'], 'Stereo mikroskop iki ayrı optik yolla iki göze ayrı görüntü verir; bu sayede örnek düşük büyütmede derinlik algısıyla incelenebilir.'),
  ('Hücreleri mikroskopta incelemeden önce formaldehit gibi maddelerle "tespit etme" (fiksasyon) işleminin amacı nedir?', 'Hücre yapılarını bozulmadan oldukları yerde sabitlemek', ['Hücreleri canlı tutup bölünmelerini hızlandırmak', 'Hücrelerin rengini tamamen gidermek', 'Hücrelerin DNA\'sını çoğaltmak'], 'Tespit maddeleri proteinleri birbirine bağlayarak hücre yapısını korur ve enzimlerin hücreyi kendi kendine sindirmesini (otolizi) önler.'),
  ('Plazmoliz deneylerinde beyaz soğan yerine kırmızı soğanın dış zarının tercih edilmesinin nedeni nedir?', 'Renkli kofulun büzülmeyi göstermesi', ['Kırmızı soğan hücrelerinin hücre duvarı taşımayıp kolay büzülmesi', 'Kırmızı soğanın tuzdan etkilenmemesi', 'Kırmızı soğan hücrelerinin daha hızlı bölünmesi'], 'Kırmızı soğan epidermis hücrelerinin kofulları renkli pigment içerir; tuzlu suda kofulun küçülmesi ve zarın çeperden ayrılması bu renk sayesinde boyasız olarak kolayca izlenir.'),
  ('Akıcı mozaik modelinde "mozaik" sözcüğü zarın hangi özelliğini anlatır?', 'Proteinlerin lipit içinde serpiştirilmiş olması', ['Zarın renkli pigmentlerden oluşan, ışıkta parlayan bir yüzey taşıması', 'Zarın sürekli bölünüp çoğalmasını', 'Zarın yalnız tek tip molekülden yapılmasını'], 'Mozaik, farklı parçaların bir araya gelerek oluşturduğu deseni anlatır; zarda da çeşitli proteinler lipit çift katmanı içinde serpiştirilmiş hâldedir. "Akıcı" ise bu bileşenlerin hareket edebilmesini anlatır.'),
  ('Bir öğrenci "Hücre zarı yalnızca hayvan hücrelerinde bulunur; bitki ve bakteri hücrelerinde onun yerine hücre duvarı vardır" diyor. Bu ifadenin değerlendirmesi nedir?', 'Yanlıştır; zar bütün hücrelerde vardır', ['Doğrudur; hücre duvarı zarın görevini üstlenir', 'Doğrudur; bakterilerde hiçbir zar bulunmaz', 'Yanlıştır; çünkü hayvan hücrelerinde de selülozdan bir duvar bulunur'], 'Hücre zarı bütün canlı hücrelerin ortak yapısıdır. Bitki, mantar ve bakteri hücrelerinde zarın dışında ayrıca bir hücre duvarı bulunur; duvar seçici geçirgenlik sağlamaz.'),
  ('Aşağıdaki organel-görev eşleştirmelerinden hangisi yanlıştır?', 'Peroksizom – protein sentezi', ['Ribozom – polipeptit sentezi', 'Lizozom – hücre içinde sindirim', 'Düz ER – lipit sentezi'], 'Peroksizomlar oksidasyon tepkimeleri ve H₂O₂ yıkımıyla görevlidir; protein sentezi ribozomlarda yapılır.'),
  ('Hayvan hücrelerinde sitoplazmanın organeller dışındaki sıvı kısmına ne ad verilir?', 'Sitozol', ['Nükleoplazma', 'Stroma', 'Matriks'], 'Sitoplazma organeller ile sitozolden oluşur; sitozol enzimler, iyonlar ve hücre iskeletini içeren jel kıvamlı sıvıdır. Stroma kloroplastın, matriks mitokondrinin iç sıvısıdır.'),
  ('Çekirdek zarının içini dolduran ve kromatin ile çekirdekçiğin içinde bulunduğu sıvıya ne ad verilir?', 'Nükleoplazma', ['Sitozol', 'Stroma', 'Tonoplast sıvısı'], 'Çekirdeğin iç sıvısı nükleoplazmadır; DNA eşlenmesi ve RNA sentezi için gereken enzimleri ve nükleotitleri barındırır.'),
  ('Kanal proteinleriyle gerçekleşen madde geçişi için hangisi doğrudur?', 'Derişim farkı yönünde ve ATP harcanmadan olur', ['Derişim farkına karşı ve ATP harcanarak olur', 'Maddenin keseciklere paketlenmesiyle olur', 'Yalnızca büyük proteinleri taşır'], 'Kanal proteinleri suyu ya da belirli iyonları derişim (elektrokimyasal) farkı yönünde geçirir; bu bir pasif taşımadır ve doğrudan enerji gerektirmez.'),
  ('Su yosunu (Elodea) yaprağı derişik tuzlu suya konup mikroskopta incelendiğinde kloroplastların hücrenin ortasında bir yığın hâlinde toplandığı görülür. Bunun nedeni nedir?', 'Sitoplazmanın çeperden çekilmesi', ['Kloroplastların tuzla birleşip çökmesi', 'Hücre duvarının içe doğru göçmesi', 'Kloroplastların bölünüp çoğalması'], 'Hipertonik ortamda hücre su kaybeder; zar ve sitoplazma çeperden ayrılarak büzülür (plazmoliz). Kloroplastlar sitoplazmada olduğu için onlar da ortada toplanmış görünür.'),
  ('Hücre zarının seçici geçirgenliğini yitirmesi durumunda hücrede ilk ortaya çıkması beklenen sorun hangisidir?', 'İç ve dış ortamın eşitlenmesi', ['Ribozomların çekirdeğe göç etmesi', 'Mitokondri DNA\'sının çoğalması', 'Hücre duvarının kalınlaşması'], 'Seçici geçirgen zar hücre içi ortamı dış ortamdan farklı tutar. Bu özellik yitirilirse iyon ve madde farkları ortadan kalkar ve hücre işlevlerini sürdüremez.'),
  ('Tipik bir hayvan hücresinde aşağıdaki iyonlardan hangisinin derişimi hücre içinde hücre dışındakinden çok daha yüksektir?', 'K⁺', ['Na⁺', 'Cl⁻', 'Ca²⁺'], 'Na⁺/K⁺ pompasının çalışması sonucunda K⁺ hücre içinde, Na⁺ ise hücre dışında yüksek derişimdedir; Cl⁻ ve Ca²⁺ de hücre dışında daha boldur.'),
  ('Pek çok hücrede toplam zar yüzeyinin yarıdan fazlasını hangi yapının zarı oluşturur?', 'Endoplazmik retikulum', ['Hücre zarı', 'Çekirdeğin çift katlı zarı', 'Lizozom zarı'], 'ER, hücre içinde kesintisiz bir zar ağı oluşturur; karaciğer ve salgı hücrelerinde ER zarı toplam zarın yarısından fazlasını kapsayabilir.'),
  ('Ribozomların çapı yaklaşık ne kadardır?', '25–30 nanometre', ['25–30 mikrometre', '2–3 milimetre', '0,25 nanometre'], 'Ribozomlar yaklaşık 25–30 nm büyüklüğündedir; ışık mikroskobunun ayırma sınırının çok altında kaldıkları için yalnız elektron mikroskobunda seçilebilir.'),
  ('Çekirdek porlarının tıkandığı varsayılan bir ökaryot hücrede ilk aksayacak süreç hangisidir?', 'mRNA\'nın ribozomlara ulaşması', ['Oksijenin hücreye difüzyonu', 'Hücre zarından suyun geçmesi', 'Glikozun sitoplazmada parçalanarak enerji vermesi'], 'Çekirdekte yazılan mRNA\'lar porlardan sitoplazmaya çıkar; porlar tıkanırsa yeni proteinler sentezlenemez. Oksijen difüzyonu ve glikoliz ise çekirdekle doğrudan ilişkili değildir.'),
  ('Silleri işlevsiz hâle gelen bir paramesyum için aşağıdakilerden hangisi beklenir?', 'Hem hareket hem besin alımı aksar', ['Yalnız kontraktil kofulu çalışmayı durdurur', 'Fotosentez yapmaya başlar', 'Çekirdek sayısı artar'], 'Paramesyum siller sayesinde yüzer; ağız oluğundaki siller de besin parçacıklarını hücre ağzına sürükler. Siller durunca hem hareket hem beslenme bozulur.'),
  ('Lizozom bulunmayan mutant bir makrofajın bakterileri yutabildiği hâlde enfeksiyonu durduramaması nasıl açıklanır?', 'Yutulan bakterileri sindiremez', ['Bakterileri hiç yutamaz', 'Bakterilere antikor yapıştıramaz', 'Bakterileri ekzositozla dışarı atamaz'], 'Fagositoz yutma aşamasıdır; yutulan bakteriyi öldürüp parçalayan ise lizozom enzimleri ve bu bölmenin asitliğidir. Lizozom olmadan bakteri hücre içinde yaşamaya devam edebilir.'),
  ('Bir bitki hücresinde tonoplasttaki H⁺ pompaları durdurulursa merkezi kofulun içi nasıl değişir?', 'Asitliği azalır', ['Asitliği artar', 'Hacmi kesinlikle iki katına çıkar', 'İçine sitoplazma dolar'], 'Koful içindeki asitliği tonoplasttaki proton pompaları sağlar; pompalar durunca protonlar dışarı sızar ve kofulun pH\'ı yükselir.'),
  ('Bir öğrenci "Osmoz yalnızca canlı hücrelerde gerçekleşebilir" diyor. Bu görüşü çürütmek için en uygun gözlem hangisidir?', 'Diyaliz torbasının suda şişmesi', ['Bir alyuvarın saf suda patlaması', 'Solmuş marulun suda dikleşmesi', 'Paramesyumun kontraktil kofulunun düzenli aralıklarla boşalması'], 'Diyaliz torbası cansız bir yarı geçirgen zardır; içinde osmoz gerçekleşmesi olayın canlılıktan değil, seçici geçirgen zar ve derişim farkından kaynaklandığını gösterir.'),
  ('Bir öğrenci "Hücrenin bütün DNA\'sı çekirdekte bulunur" diyor. Bu ifade için en doğru değerlendirme hangisidir?', 'Eksiktir; organellerde de DNA vardır', ['Doğrudur; çekirdek dışında hiç DNA bulunmaz', 'Yanlıştır; DNA\'nın tamamı ribozomlarda bulunur', 'Doğrudur; ancak yalnız bitkilerde geçerlidir'], 'Ökaryot DNA\'sının büyük kısmı çekirdektedir; ancak mitokondri ve kloroplastlar küçük halkasal genomlar taşır.'),
  ('Bir öğrenci "Kolaylaştırılmış difüzyon bir taşıyıcı protein kullandığı için aktif taşıma sayılmalıdır" diyor. Bu görüş neden yanlıştır?', 'Madde derişim farkı yönünde taşınır', ['Kolaylaştırılmış difüzyonda hiç protein kullanılmaz', 'Aktif taşımada hiç protein kullanılmaz', 'Kolaylaştırılmış difüzyon yalnız bakterilerde görülür'], 'Aktif ya da pasif taşımayı ayıran ölçüt protein kullanımı değil, maddenin derişim farkına karşı taşınıp taşınmaması ve bunun için enerji harcanıp harcanmamasıdır.'),
  ('Bir öğrenci "Hücre zarı bir kalkan gibi hücreyi dış ortamdan tamamen yalıtır" diyor. Bu benzetmenin zayıf yönü nedir?', 'Zar seçicidir, madde alışverişine izin verir', ['Zar yalnızca bitki hücrelerinde bulunur', 'Zar hücrenin içinde yer alır', 'Zar sert ve hareketsiz bir yapıdır'], 'Zar tam bir engel değil, seçici bir sınırdır; besinlerin alınması, atıkların atılması ve sinyallerin iletilmesi bu sınır üzerinden sürekli gerçekleşir.'),
  ('Çekirdekçik (nükleolus) için aşağıdakilerden hangisi doğrudur?', 'Zarla çevrili değildir', ['Çift zarla çevrilidir', 'Kendi halkasal DNA\'sı vardır', 'Yalnız prokaryotlarda bulunur'], 'Çekirdekçik, çekirdek içinde rRNA genlerinin çevresinde toplanan yoğun bir bölgedir; çevresinde zar bulunmaz.'),
  ('Bir yaprak mezofil hücresinde kloroplast ile mitokondri büyüklük bakımından karşılaştırıldığında genellikle hangisi doğrudur?', 'Kloroplast daha büyüktür', ['Mitokondri çok daha büyüktür', 'İkisi de ribozomdan küçüktür', 'İkisi de çekirdekten büyüktür'], 'Kloroplastlar genellikle 5–10 µm uzunluğundadır; mitokondriler ise çoğunlukla 1–2 µm uzunluğunda ve yaklaşık 0,5–1 µm çapındadır.'),
  ('Lizozomlarda bulunan enzimler arasında aşağıdakilerden hangisi yer almaz?', 'Katalaz', ['Proteaz', 'Nükleaz', 'Lipaz'], 'Lizozomlar protein, nükleik asit, lipit ve karbonhidratları parçalayan çok sayıda asit hidrolaz içerir. Katalaz ise peroksizomlara özgü bir enzimdir.'),
  ('Şeker pancarının kök hücrelerinde yüksek derişimde biriktirilen sakaroz hücrenin hangi bölümünde depolanır?', 'Merkezi kofulda', ['Hücre duvarında', 'Çekirdekte', 'Ribozomlarda'], 'Şeker pancarı sakarozu kök hücrelerinin merkezi kofullarında depolar; tonoplasttaki taşıyıcılar sakarozu derişim farkına karşı kofula pompalar.'),
  ('Fasulye ve bezelye gibi tohumların depo dokularında proteinler hangi yapılarda birikir?', 'Protein depolayan kofullarda', ['Kloroplast tilakoitlerinde', 'Hücre duvarının selüloz liflerinde', 'Mitokondri kristalarında'], 'Tohum gelişirken depo proteinleri ER ve Golgi aracılığıyla özel protein depo kofullarına taşınır; çimlenmede bu proteinler yıkılarak fideye amino asit sağlar.'),
  ('Bir hayvan hücresinde genellikle en büyük organel hangisidir?', 'Çekirdek', ['Ribozom', 'Lizozom', 'Peroksizom'], 'Çekirdek genellikle 5–10 µm çapındadır ve ışık mikroskobunda en kolay seçilen organeldir. Bitki hücrelerinde ise merkezi koful çoğu zaman çekirdekten de büyüktür.'),
  ('Mitokondri matriksinde bulunan yapılar arasında aşağıdakilerden hangisi yer almaz?', 'Klorofil molekülleri', ['Mitokondri DNA\'sı', 'Ribozomlar', 'Krebs döngüsü enzimleri'], 'Matriks mitokondri DNA\'sı, ribozomlar ve pek çok metabolizma enzimi içerir; klorofil yalnız kloroplastın tilakoit zarında bulunur.'),
  ('Bitki ve hayvan hücrelerinin biçimleri karşılaştırıldığında bitki hücrelerinin genellikle daha düzenli, köşeli bir biçimde kalmasının nedeni nedir?', 'Sert hücre duvarları', ['Çekirdek taşımamaları', 'Hücre iskeleti bulunmaması', 'Hücre zarlarının hayvan hücrelerindekinden daha kalın olması'], 'Hücre duvarı hücre biçimini sabitler. Duvarı olmayan hayvan hücreleri ise hücre iskeleti sayesinde çok farklı biçimler alabilir ve biçim değiştirebilir.'),
  ('Bir bakteri hücresinde aşağıdaki süreçlerden hangisi hücre zarında gerçekleşir?', 'Oksijenli solunumda ATP üretimi', ['Ribozom alt birimlerinin çekirdekçikte kurulması', 'Proteinlerin Golgi\'de paketlenmesi', 'Lizozomda besin sindirimi'], 'Bakterilerde mitokondri yoktur; elektron taşıma zinciri ve ATP sentaz hücre zarına yerleşmiştir. Çekirdekçik, Golgi ve lizozom ise prokaryotlarda bulunmaz.'),
  ('Çok uzun bir bakteri hücresinin, içinde difüzyonla madde dağıtımını kolaylaştırmak için aldığı biçim aşağıdakilerden hangisidir?', 'İnce ve uzun biçim', ['Kalın ve tam küre biçim', 'Küp biçim', 'İçi dolu kalın disk biçim'], 'İnce ve uzun biçimde hücrenin hiçbir noktası yüzeye uzak değildir; yüzey/hacim oranı yüksek kaldığı için madde alışverişi büyük hacimde bile yeterli olur.'),
  ('Bir öğrenci "Hücre iskeleti, insan iskeleti gibi kalıcı ve değişmeyen bir yapıdır" diyor. Bu benzetmenin hatası nedir?', 'Hücre iskeleti dinamik bir yapıdır', ['Hücre iskeleti yalnız bitkilerde bulunur, hayvanlarda yoktur', 'Hücre iskeleti hücre dışında yer alır', 'Hücre iskeleti lipitlerden yapılır'], 'Hücre iskeleti elemanları gereksinime göre dakikalar içinde kurulup sökülebilir; bu esneklik hücre hareketini, bölünmeyi ve madde taşımayı mümkün kılar.'),
  ('Tek hücreli bir algin kamçısı koparıldığında hücrenin bir süre sonra yeni kamçı oluşturduğu görülür. Yeni kamçının iç iskeleti hangi protein birimlerinin eklenmesiyle uzar?', 'Tübülin', ['Aktin', 'Kollajen', 'Keratin'], 'Kamçının içindeki 9+2 düzenli yapı mikrotübüllerden oluşur; yeni kamçı bazal cisimden itibaren ucuna tübülin eklenerek uzar.'),
  ('Sil ve kamçılardaki dinein kollarının çalışması için doğrudan gereken enerji molekülü hangisidir?', 'ATP', ['NADPH', 'Glikoz', 'GTP\'siz tübülin'], 'Dinein kolları ATP\'yi hidrolizleyerek komşu mikrotübül çiftini iter; ATP olmadan sil ve kamçılar hareket edemez.'),
  ('Atardamar duvarları ve akciğerler gibi gerildikten sonra eski biçimine dönmesi gereken dokulara bu özelliği kazandıran hücre dışı matriks proteini hangisidir?', 'Elastin', ['Keratin', 'Aktin', 'Hemoglobin'], 'Elastin lifleri lastik gibi gerilip bırakıldığında eski boyuna döner; bu nedenle esneme ve geri toplanma gereken dokularda boldur. Kollajen ise gerilmeye karşı dayanıklılık sağlar.'),
  ('Kollajen molekülünün temel yapısı hangisidir?', 'Üç zincirli üçlü sarmal', ['Çift sarmallı, nükleotitlerden oluşan bir molekül', 'Tek zincirli düz bir polisakkarit', 'Dallanmış bir lipit zinciri'], 'Her kollajen molekülü birbirine sarılmış üç uzun polipeptit zincirinden oluşur; bu moleküller yan yana dizilerek çok dayanıklı lifler oluşturur.'),
  ('Ökaryot hücrelerde çekirdek zarının hangi katmanının sitoplazmaya bakan yüzü granüllü ER gibi ribozomlarla kaplı olabilir?', 'Dış çekirdek zarı', ['İç çekirdek zarı', 'Çekirdek laminası', 'Çekirdekçik'], 'Dış çekirdek zarı ER zarının devamıdır ve üzerinde protein sentezleyen ribozomlar bulunabilir; iç zar ise laminaya ve kromatine bakar.'),
  ('Beyaz yağ dokusu hücrelerinde hücre hacminin büyük kısmını kaplayan yapı hangisidir?', 'Tek büyük lipit damlası', ['Çok sayıda mitokondri', 'Büyük merkezi koful', 'Yoğun granüllü ER'], 'Beyaz yağ hücrelerinde trigliseritler tek bir büyük damla hâlinde birikir; çekirdek ve sitoplazma hücrenin kenarına doğru itilmiş ince bir şerit gibi kalır.'),
  ('Karaciğer ve kas hücrelerinde glikojen sitoplazmada nasıl bulunur?', 'Zarsız tanecikler hâlinde', ['Lizozomların içinde', 'Çift zarlı keseciklerde', 'Mitokondri matriksinde'], 'Glikojen sitozolde, kendisini yapan ve yıkan enzimlerle birlikte zarsız tanecikler hâlinde depolanır; böylece gerektiğinde hızla glikoza dönüştürülebilir.'),
  ('Tamamen iyonlaşan 0,1 M NaCl ile 0,1 M glikoz aynı çözeltide bulunuyorsa çözeltinin toplam osmotik derişimi kaç osmol/L\'dir?', '0,3', ['0,2', '0,1', '0,15'], 'NaCl 2 tanecik verir (0,1 × 2 = 0,2), glikoz 1 tanecik verir (0,1). Toplam 0,2 + 0,1 = 0,3 osmol/L olur.'),
  ('Kalp kası hücresindeki Na⁺/Ca²⁺ değiştiricisi her döngüde 3 Na⁺ içeri alıp 1 Ca²⁺ dışarı atıyor. Hücreden 1000 Ca²⁺ iyonu atıldığında hücreye kaç Na⁺ girmiş olur?', '3000', ['1000', '333', '1500'], 'Her Ca²⁺ için 3 Na⁺ girer: 1000 × 3 = 3000 Na⁺. Bu Na⁺ daha sonra Na⁺/K⁺ pompasıyla ATP harcanarak dışarı atılır.'),
  ('Peroksizomların özellikle bol bulunduğu iki memeli organı hangileridir?', 'Karaciğer ve böbrek', ['Deri ve kemik', 'Kas ve yağ dokusu', 'Göz merceği ve kıkırdak'], 'Karaciğer ve böbrek hücreleri zararlı maddeleri etkisizleştirme ve yağ asidi yıkımında yoğun çalıştığından çok sayıda peroksizom içerir.'),
  ('Nergis ve kadife çiçeği gibi bitkilerin sarı-turuncu taç yapraklarındaki pigmentler hangi plastitlerde bulunur ve bitkiye nasıl yarar sağlar?', 'Kromoplastlarda; tozlaşmayı kolaylaştırır', ['Kloroplastlarda; fotosentezi artırarak', 'Amiloplastlarda; nişasta depolayarak', 'Etioplastlarda; karanlıkta büyümeyi ve gövde uzamasını sağlayarak'], 'Karotenoit taşıyan kromoplastlar çiçeklere ve meyvelere sarı, turuncu ve kırmızı renk verir; bu renkler tozlaşmayı ve tohum dağılımını sağlayan hayvanları çeker.'),
  ('Pek çok ökaryot hücrede hücredeki toplam proteinin önemli bir kısmını oluşturan ve genellikle en bol bulunan hücre iskeleti proteini hangisidir?', 'Aktin', ['Keratin', 'Lamin', 'Dinein'], 'Aktin pek çok hücrede toplam proteinin yüzde 5–10\'unu oluşturabilir; mikrofilamentlerin yapı birimi olarak hücre biçimi, hareket ve bölünmede görev alır.'),
  ('Boğaz ağrısında ılık tuzlu suyla gargara yapılmasının şişmiş dokuyu rahatlatmasının osmotik açıklaması nedir?', 'Fazla sıvıyı osmozla çekmesi', ['Tuzun boğaz hücrelerine girip onları şişirmesi', 'Tuzlu suyun hipotonik olup dokuya su vermesi', 'Tuzun mikropların DNA\'sını onarması'], 'Tuzlu su mukozaya göre hipertoniktir; dokudaki fazla sıvı osmozla yüzeye çekilir ve şişlik azalır.'),
  ('Kontakt lens saklama çözeltilerinin göz yaşıyla izotonik hazırlanmasının nedeni nedir?', 'Hücrelerin su dengesini korumak', ['Lensin rengini korumak', 'Gözdeki mikropları osmozla öldürmek', 'Lensi daha sert yapmak'], 'İzotonik çözeltide kornea yüzeyindeki hücreler net su kazanmaz ya da kaybetmez; bu yüzden şişme, büzülme ve yanma hissi oluşmaz.'),
  ('Robert Hooke\'un 1665\'te mantar dokusunda gördüğü ve "hücre" adını verdiği boş odacıklar aslında neydi?', 'Ölü hücrelerin boş çeperleri', ['Canlı hücrelerin çekirdekleri', 'Bakteri kolonileri', 'Bitki hücrelerinin kloroplastları'], 'Mantar dokusu ölü hücrelerden oluşur; Hooke içeriği kaybolmuş, yalnız çeperleri kalmış hücreleri görmüş ve bunları manastır odacıklarına benzetmiştir.'),
  ('Pamuk lifinin neredeyse saf selülozdan oluşması, bu lifin hangi yapı olmasıyla açıklanır?', 'Tek bir tohum hücresinin uzamış duvarı', ['Pamuk bitkisinin kök hücrelerinin çekirdeği', 'Hayvan hücrelerinin salgıladığı kollajen', 'Pamuk yaprağındaki kloroplast zarları'], 'Her pamuk lifi tohum epidermisindeki tek bir hücrenin uzamasıyla oluşur; hücre olgunlaşıp öldüğünde geriye kalın selüloz duvarı kalır.'),
  ('Elektron mikroskobu fotoğraflarında görülen renkler için hangisi doğrudur?', 'Renkler sonradan eklenir', ['Elektronlar yapıların gerçek renklerini gösterir', 'Renkler kullanılan ağır metallerin doğal rengidir', 'Renkler örneğin canlı olduğunu gösterir'], 'Elektron mikroskobu görünür ışık kullanmadığından yalnız gri tonlarda görüntü verir; yayınlardaki renkler yapıları ayırt etmek için sonradan eklenir.'),
  ('Organel ayırma deneylerinde dokular buz gibi soğuk ve izotonik bir şeker tamponunda parçalanır. Bu koşulların amacı nedir?', 'Organelleri sağlam korumak', ['Organellerin fotosentez yapmasını sağlamak', 'Organelleri birbirine yapıştırmak', 'Hücrelerin bölünmesini hızlandırmak'], 'İzotonik ortam organellerin su alıp patlamasını engeller; soğuk ise hücreden çıkan yıkıcı enzimlerin etkinliğini yavaşlatarak organelleri korur.'),
  ('Endozomlar olgunlaşıp lizozoma dönüşürken iç ortamlarında hangi değişiklik görülür?', 'Giderek daha asidik hâle gelirler', ['Giderek daha bazik hâle gelirler', 'İçleri sitoplazmayla karışır', 'DNA kazanırlar'], 'Erken endozomun pH\'ı yaklaşık 6 iken geç endozom ve lizozomda 5\'in altına düşer; artan asitlik ligandların ayrılmasını ve sindirim enzimlerinin çalışmasını sağlar.'),
  ('Paramesyumda besin kofulları sitoplazmada dolaşırken sindirimi tamamlanmış artıklar hücre dışına nasıl atılır?', 'Belirli bir açıklıktan ekzositozla', ['Kontraktil kofuldan dışarı püskürtülerek', 'Hücre zarından difüzyonla sızarak', 'Kamçıyla dışarı fırlatılarak'], 'Paramesyumda sindirilemeyen artıklar hücre anüsü (sitoprokt) denilen belirli bir zar bölgesinden kofulun zarla kaynaşmasıyla dışarı bırakılır.'),
  ('Hücre zarına sürekli eklenen yeni fosfolipit ve zar proteinleri büyük ölçüde nereden gelir?', 'ER\'de yapılıp Golgi keseciklerince zara taşınır', ['Hücre dışındaki sıvıdan doğrudan zara yapışır', 'Çekirdek zarından kopup zara gider', 'Mitokondride yapılıp porlardan çıkar'], 'Zar bileşenleri ER\'de sentezlenir, Golgi\'de işlenir ve kesecikler hücre zarıyla kaynaştığında zara eklenir; bu sürekli akış zar yenilenmesini sağlar.'),
  ('Aşağıdaki organellerden hangisi iç zar sisteminin bir parçası sayılmaz?', 'Mitokondri', ['Golgi cisimciği', 'Lizozom', 'Endoplazmik retikulum'], 'İç zar sistemi kesecik akışıyla birbirine bağlı ER, Golgi, lizozom, kofullar ve hücre zarından oluşur. Mitokondri ve kloroplast kendi bölünmeleriyle çoğalır ve bu akışa katılmaz.'),
  ('Armut yerken ağızda hissedilen hafif kumlu doku, meyve etinde dağınık bulunan ve kalın, odunlaşmış çeperli hangi hücrelerden kaynaklanır?', 'Taş hücreleri', ['Bekçi hücreler', 'Kök tüyü hücreleri', 'Kalburlu boru hücreleri'], 'Sklereitlerin ikincil çeperleri çok kalın ve ligninle sertleşmiştir; armut ve ayva etindeki küçük sert taneciklerin kaynağı bu hücrelerdir.'),
  ('Işık mikroskobunda incelenecek bitki ya da hayvan dokusundan alınan kesitlerin çok ince hazırlanmasının temel nedeni nedir?', 'Işığın örnekten geçebilmesi', ['Örneğin daha hızlı kuruması', 'Elektronların örneğe girip görüntü oluşturabilmesi', 'Örneğin daha ağır olması'], 'Işık mikroskobunda görüntü örnekten geçen ışıkla oluşur; kalın kesitler ışığı geçirmez ve hücre katmanları üst üste binerek ayrıntıyı bozar.'),
  ('Bir öğrenci incelediği hücrede kitin içeren bir hücre duvarı, mitokondriler ve çekirdek görüyor; kloroplast ise bulunmuyor. Bu hücre en büyük olasılıkla hangi gruptandır?', 'Mantar', ['Bitki', 'Bakteri', 'Hayvan'], 'Kitinli çeper mantarlara özgüdür; çekirdek ve mitokondri ökaryot olduğunu, kloroplast yokluğu da bitki olmadığını gösterir.'),
  ('Yoğun terleyen sporculara önerilen "izotonik" spor içeceklerinin sudan farkı nedir?', 'Tuz ve şeker derişiminin vücut sıvılarına yakın olması', ['Hiç su içermemesi', 'Kan hücrelerini patlatacak kadar seyreltik olması', 'Yalnızca saf alkol içermesi'], 'İzotonik içecekler terle kaybedilen tuzları da yerine koyar; çözünen derişimi vücut sıvılarına yakın olduğundan hücrelerde ani su kaymalarına yol açmadan emilir.'),
  ('Hücre dışındaki bir oksijen molekülü bir hayvan hücresinin mitokondri matriksine ulaşıncaya kadar kaç lipit çift katmanından geçer?', '3', ['1', '2', '5'], 'Önce hücre zarından, sonra mitokondrinin dış ve iç zarlarından geçer: toplam 3 çift katman.'),
  ('Bir ökaryot kamçısının enine kesitinde 9+2 düzeninde kaç mikrotübül bulunur?', '20', ['11', '18', '27'], 'Dışta 9 çift (9 × 2 = 18) ve ortada 2 tek mikrotübül vardır: 18 + 2 = 20. Bazal cisimde ise 9 üçlü, yani 27 mikrotübül bulunur.'),
  ('Kahverengi yağ hücrelerinin beyaz yağ hücrelerinden farklı olarak koyu renkli görünmesinin başlıca nedeni nedir?', 'Çok sayıda mitokondri içermesi', ['Melanin pigmenti biriktirmesi', 'Kloroplast taşıması', 'Hiç lipit içermemesi'], 'Kahverengi yağ hücreleri bol mitokondri taşır; mitokondrilerdeki demir içeren sitokromlar dokuya koyu rengini verir. Bu mitokondriler enerjiyi ısıya dönüştürmede uzmanlaşmıştır.'),
  ('Bir öğrenci "Ribozomlar yalnızca granüllü ER\'nin üzerinde bulunur" diyor. Bu ifade için en doğru değerlendirme hangisidir?', 'Yanlıştır; serbest ve organel ribozomları da vardır', ['Doğrudur; ER dışında hücrenin hiçbir yerinde ribozom bulunmaz', 'Doğrudur; ancak yalnız bitki hücrelerinde', 'Yanlıştır; ribozomlar yalnız çekirdekte bulunur'], 'Ribozomların bir kısmı ER\'ye bağlıdır; ancak sitozolde serbest ribozomlar, mitokondri ve kloroplastın içinde de kendi ribozomları bulunur.'),
  ('Bir öğrenci "Aktif taşıma maddeleri yalnızca hücrenin içine almak için kullanılır" diyor. Bu ifadeyi çürüten örnek hangisidir?', 'Na⁺/K⁺ pompasının Na⁺ atması', ['Oksijenin hücreye difüzyonla girmesi', 'Suyun akuaporinden hücreye girmesi', 'Glikozun taşıyıcı proteinle derişim farkı yönünde hücreye girmesi'], 'Aktif taşıma maddeleri derişim farkına karşı her iki yönde de taşıyabilir; Na⁺/K⁺ pompası Na⁺\'u dışarı, K⁺\'u içeri pompalar.'),
  ('Bir öğrenci "Difüzyon yalnızca sıvılarda gerçekleşir" diyor. Bu genellemeyi çürüten gözlem hangisidir?', 'Açılan bir parfüm şişesinin kokusunun odaya yayılması', ['Mürekkebin suda dağılması', 'Şekerin çayda çözünüp yayılması', 'Tuzun çorbada dağılması'], 'Parfüm molekülleri havada yayılır; difüzyon gazlarda sıvılardan da hızlı gerçekleşir, katılarda ise çok yavaş da olsa görülebilir.'),
  ('Kas liflerinde ve kamçılı hücrelerde mitokondrilerin ATP\'nin kullanıldığı yapıların hemen yanında dizilmesi hücreye ne kazandırır?', 'ATP\'nin kullanılacağı yere kısa sürede ulaşması', ['Mitokondrilerin bölünmesinin durması', 'Mitokondrilerin fotosentez yapması', 'Hücrede ATP\'ye gerek kalmaması'], 'Mitokondriler hücre iskeleti tarafından enerji gereksiniminin yüksek olduğu bölgelere yerleştirilir; böylece ATP\'nin difüzyonla kat edeceği yol kısalır.'),
  ('İnce bağırsaktaki Na⁺-glikoz ortak taşıyıcısı (SGLT1) her döngüde 2 Na⁺ ile 1 glikozu birlikte hücreye alır. 600 glikoz molekülü alındığında hücreye kaç Na⁺ girmiş olur?', '1200', ['600', '300', '1800'], 'Her glikoz için 2 Na⁺ girer: 600 × 2 = 1200 Na⁺. Bu Na⁺ iyonları daha sonra Na⁺/K⁺ pompasıyla hücre dışına atılır.'),
  ('Sebzeler uzun süre haşlandığında yumuşamasının hücre düzeyindeki başlıca nedeni hangisidir?', 'Orta lameldeki pektinlerin çözülmesi', ['Selülozun tamamen glikoza dönüşmesi', 'Hücrelerin bölünüp çoğalması', 'Kofulların su alarak turgorun artması ve hücrelerin patlaması'], 'Isı, hücreleri birbirine bağlayan pektince zengin orta lameli çözer ve zarları bozar; turgor kaybolup hücreler birbirinden ayrıldığı için doku yumuşar.'),
  ('Meyveler olgunlaşırken yumuşamasında hücre duvarında hangi değişiklik önemli rol oynar?', 'Duvar polisakkaritlerinin yıkılması', ['Hücre duvarına yoğun lignin çökerek dokunun sertleşmesi', 'Hücre duvarının kalınlaşması', 'Kofulların küçülüp kaybolması'], 'Olgunlaşmada pektinaz gibi enzimler duvar matriksini ve orta lameli yıkar; hücreler arası bağlantı gevşer ve meyve yumuşar.'),
  ('Okul laboratuvarında muz ya da çilekten DNA elde edilirken ezilmiş meyveye bulaşık deterjanı eklenmesinin amacı nedir?', 'Zar lipitlerini çözmek', ['DNA\'yı renklendirip görünür yapmak', 'Hücre duvarını selüloza dönüştürüp DNA\'yı serbest bırakmak', 'DNA\'yı çoğaltmak'], 'Deterjan amfipatik moleküllerden oluşur ve zarlardaki lipitleri misellere ayırarak zarları parçalar; böylece çekirdekteki DNA dışarı çıkar.'),
  ('Alkol bazlı el dezenfektanlarının bakterileri öldürmesindeki başlıca etki hangisidir?', 'Zar yapısını bozup proteinlerin biçimini değiştirmesi', ['Bakterilere besin sağlaması', 'Bakterilerin DNA\'sını onarması', 'Bakterilerin hücre duvarını kalınlaştırması'], 'Yüksek derişimli alkol zar lipitlerini çözer ve proteinlerin katlanmasını bozar; zarı bozulup enzimleri çalışamayan bakteri ölür.'),
  ('Bir öğrenci "Organel" kavramını yalnızca zarla çevrili yapılar için kullanıyor. Bu tanım benimsenirse aşağıdakilerden hangisi organel sayılmaz?', 'Ribozom', ['Lizozom', 'Peroksizom', 'Mitokondri'], 'Ribozomlar zarla çevrili değildir; yalnız zarlı yapıları organel sayan dar tanımda ribozomlar organel dışında kalır. Lizozom, peroksizom ve mitokondri zarlıdır.'),
  ('Kuru soğanın etli katmanlarından alınan zar preparatında yeşil kloroplastların görülmemesinin nedeni nedir?', 'Bu katmanların ışık almayan depo yaprakları olması', ['Soğan hücrelerinin hücre duvarı taşımaması', 'Soğan hücrelerinin çekirdeksiz olması', 'Kloroplastların boyayla eritilmesi'], 'Soğanın etli katmanları besin depolayan, toprak altında ışıksız gelişen yapraklardır; bu hücrelerde plastitler kloroplasta dönüşmez.'),
  ('Soğan zarı hücreleri boyanıp ışık mikroskobunda 400 kat büyütmeyle incelendiğinde aşağıdaki yapılardan hangisi görülemez?', 'Ribozomlar', ['Hücre duvarı', 'Çekirdek', 'Hücrelerin sınırları'], 'Hücre duvarı ve çekirdek ışık mikroskobunda kolayca seçilir; yaklaşık 25 nm büyüklüğündeki ribozomlar ise ancak elektron mikroskobuyla görülebilir.'),
  ('Bir bitki hücresinin kofulunda depolanan pigmentlerin rengi kofulun pH\'ına göre değişebilir. Kırmızı lahana suyunun asitli ortamda kırmızı, bazik ortamda yeşil-sarı renge dönmesi bu pigmentlerin hangi özelliğini gösterir?', 'pH göstergesi gibi davranmaları', ['Fotosentez yapmaları', 'Lipitlerde çözünmeleri', 'Kloroplastlarda bulunmaları'], 'Antosiyaninler ortamın pH\'ına göre yapı değiştirip farklı renk alır; bu yüzden kırmızı lahana suyu basit bir asit-baz göstergesi olarak kullanılabilir.'),
];
